import React, { useState, useRef, useEffect } from 'react';
import { GeminiService } from '../services/geminiService';

const VOICES = {
  male: [
    { id: 'Fenrir', label: 'طارق (ذكوري - رخيم)' },
    { id: 'Puck', label: 'باسل (ذكوري - واضح)' },
    { id: 'Charon', label: 'عمرو (ذكوري - عميق)' },
  ],
  female: [
    { id: 'Kore', label: 'سلمى (أنثوي - نقي)' },
    { id: 'Aoede', label: 'ريم (أنثوي - هادئ)' },
    { id: 'Zephyr', label: 'نور (أنثوي - متزن)' },
  ]
};

// Helper to convert AudioBuffer to WAV Blob
const bufferToWave = (abuffer: AudioBuffer, len: number) => {
  const numOfChan = abuffer.numberOfChannels;
  const length = len * numOfChan * 2 + 44;
  const buffer = new ArrayBuffer(length);
  const view = new DataView(buffer);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write WAVE header
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  setUint32(0x20746d66); // "fmt " chunk
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(abuffer.sampleRate);
  setUint32(abuffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this example)

  setUint32(0x61746164); // "data" - chunk
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for(i = 0; i < abuffer.numberOfChannels; i++)
    channels.push(abuffer.getChannelData(i));

  while(pos < len) {
    for(i = 0; i < numOfChan; i++) {
      sample = Math.max(-1, Math.min(1, channels[i][pos])); // clamp
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; // scale to 16-bit signed int
      view.setInt16(44 + offset, sample, true); 
      offset += 2;
    }
    pos++;
  }

  return new Blob([buffer], {type: "audio/wav"});

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }
  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }
};

const VoiceStudio: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'tts' | 'lab'>('tts');

  // --- TTS State ---
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // --- Voice Lab State ---
  const [isRecording, setIsRecording] = useState(false);
  const [labAudioBlob, setLabAudioBlob] = useState<Blob | null>(null);
  const [processedBlob, setProcessedBlob] = useState<Blob | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [labAudioUrl, setLabAudioUrl] = useState<string | null>(null);

  // Lab Settings
  const [enableDenoise, setEnableDenoise] = useState(true);
  const [enableEnhance, setEnableEnhance] = useState(true);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);

  // --- TTS Functions ---
  const createMp3Blob = (samples: Int16Array, sampleRate: number = 24000) => {
    // @ts-ignore
    const lame = window.lamejs;
    if (!lame) return null;
    const mp3encoder = new lame.Mp3Encoder(1, sampleRate, 128);
    const mp3Data = [];
    const sampleBlockSize = 1152;
    for (let i = 0; i < samples.length; i += sampleBlockSize) {
      const sampleChunk = samples.subarray(i, i + sampleBlockSize);
      const mp3buf = mp3encoder.encodeBuffer(sampleChunk);
      if (mp3buf.length > 0) mp3Data.push(mp3buf);
    }
    const mp3buf = mp3encoder.flush();
    if (mp3buf.length > 0) mp3Data.push(mp3buf);
    return new Blob(mp3Data, { type: 'audio/mp3' });
  };

  const handleSpeak = async () => {
    if (!text) return;
    if (audioUrl) { URL.revokeObjectURL(audioUrl); setAudioUrl(null); }
    setIsPlaying(false);
    setLoading(true);
    try {
        const rawBuffer = await GeminiService.generateSpeech(text, selectedVoice);
        const int16Data = new Int16Array(rawBuffer);
        const mp3Blob = createMp3Blob(int16Data, 24000);
        if (mp3Blob) {
            const url = URL.createObjectURL(mp3Blob);
            setAudioUrl(url);
            setTimeout(() => { if (audioRef.current) { audioRef.current.play(); setIsPlaying(true); } }, 100);
        }
    } catch (error) {
        console.error(error);
        alert("حدث خطأ أثناء توليد الصوت.");
    } finally {
        setLoading(false);
    }
  };

  // --- Voice Lab Functions ---

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setLabAudioBlob(audioBlob);
        setLabAudioUrl(URL.createObjectURL(audioBlob));
        setProcessedBlob(null); // Reset processed if new recording
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
      visualize(stream);
    } catch (err) {
      console.error(err);
      alert("يرجى السماح بصلاحية الميكروفون للتسجيل.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
      setIsRecording(false);
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const source = audioCtx.createMediaStreamSource(stream);
    const analyzer = audioCtx.createAnalyser();
    analyzer.fftSize = 256;
    source.connect(analyzer);

    const bufferLength = analyzer.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if(!canvas) return;
    const ctx = canvas.getContext('2d');
    if(!ctx) return;

    const draw = () => {
        animationFrameRef.current = requestAnimationFrame(draw);
        analyzer.getByteFrequencyData(dataArray);
        ctx.fillStyle = 'rgb(15, 23, 42)'; // Background
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const barWidth = (canvas.width / bufferLength) * 2.5;
        let barHeight;
        let x = 0;

        for(let i = 0; i < bufferLength; i++) {
            barHeight = dataArray[i] / 2;
            const r = barHeight + 25 * (i/bufferLength);
            const g = 250 * (i/bufferLength);
            const b = 50;

            ctx.fillStyle = `rgb(${r},${g},${b})`;
            ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
            x += barWidth + 1;
        }
    };
    draw();
  };

  const processAudio = async () => {
    if (!labAudioBlob) return;
    setIsProcessing(true);

    try {
        const arrayBuffer = await labAudioBlob.arrayBuffer();
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);

        // Offline Context for rendering
        const offlineCtx = new OfflineAudioContext(decodedBuffer.numberOfChannels, decodedBuffer.length, decodedBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = decodedBuffer;

        let lastNode: AudioNode = source;

        // 1. Denoise (Highpass to remove rumble + Lowpass for hiss)
        if (enableDenoise) {
            const highpass = offlineCtx.createBiquadFilter();
            highpass.type = 'highpass';
            highpass.frequency.value = 100; // Remove sub-bass rumble
            lastNode.connect(highpass);
            lastNode = highpass;

            const lowpass = offlineCtx.createBiquadFilter();
            lowpass.type = 'lowpass';
            lowpass.frequency.value = 12000; // Soften extreme highs
            lastNode.connect(lowpass);
            lastNode = lowpass;
        }

        // 2. Enhance (Compressor + EQ)
        if (enableEnhance) {
            // Dynamics Compressor for "Radio Voice" consistency
            const compressor = offlineCtx.createDynamicsCompressor();
            compressor.threshold.value = -24;
            compressor.knee.value = 30;
            compressor.ratio.value = 4; // Moderate compression
            compressor.attack.value = 0.003;
            compressor.release.value = 0.25;
            lastNode.connect(compressor);
            lastNode = compressor;

            // Presence EQ boost
            const eq = offlineCtx.createBiquadFilter();
            eq.type = 'peaking';
            eq.frequency.value = 2500; // Vocal clarity range
            eq.Q.value = 1;
            eq.gain.value = 3; // +3dB
            lastNode.connect(eq);
            lastNode = eq;
        }

        lastNode.connect(offlineCtx.destination);
        source.start();

        const renderedBuffer = await offlineCtx.startRendering();
        const waveBlob = bufferToWave(renderedBuffer, renderedBuffer.length);

        setProcessedBlob(waveBlob);
        setLabAudioUrl(URL.createObjectURL(waveBlob));

    } catch (e) {
        console.error("Audio Processing Error", e);
        alert("حدث خطأ أثناء معالجة الصوت.");
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="flex flex-col h-full p-4 md:p-8 max-w-5xl mx-auto">
       <div className="mb-6 border-b border-white/10 pb-4 flex justify-between items-end">
        <div>
            <h2 className="text-3xl font-calligraphy text-amber-400 mb-2">استوديو الصوتيات</h2>
            <p className="text-slate-400 font-light font-sans">توليد الكلام، استنساخ الصوت، وتنقيح التسجيلات.</p>
        </div>

        {/* Tab Switcher */}
        <div className="flex bg-slate-900/60 rounded-lg p-1 border border-white/10">
            <button 
                onClick={() => setActiveTab('tts')}
                className={`px-4 py-2 rounded-md font-sans text-sm transition-all ${activeTab === 'tts' ? 'bg-amber-500 text-slate-900 font-bold' : 'text-slate-400 hover:text-white'}`}
            >
                الناطق الآلي
            </button>
            <button 
                onClick={() => setActiveTab('lab')}
                className={`px-4 py-2 rounded-md font-sans text-sm transition-all ${activeTab === 'lab' ? 'bg-emerald-500 text-slate-900 font-bold' : 'text-slate-400 hover:text-white'}`}
            >
                مختبر الصوت (استنساخ)
            </button>
        </div>
      </div>

      {activeTab === 'tts' ? (
          // --- TTS View ---
          <div className="flex-1 flex flex-col gap-6 animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                     <textarea
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder="أدخل النص هنا للاستماع إليه..."
                        className="w-full bg-slate-800/40 border border-slate-600 rounded-2xl p-6 text-xl font-sans text-white focus:ring-2 focus:ring-amber-500 outline-none resize-none leading-loose min-h-[150px]"
                    />
                </div>
                <div className="bg-slate-900/40 p-4 rounded-xl border border-white/5">
                    <h3 className="text-emerald-400 font-bold mb-3 font-sans">الأصوات الذكورية</h3>
                    <div className="space-y-2">
                        {VOICES.male.map(voice => (
                            <button
                                key={voice.id}
                                onClick={() => setSelectedVoice(voice.id)}
                                className={`w-full flex items-center justify-between p-3 rounded-lg border transition-all font-sans ${selectedVoice === voice.id ? 'bg-emerald-500/20 border-emerald-500 text-emerald-100' : 'border-slate-700 text-slate-400 hover:bg-white/5'}`}
                            >
                                <span>{voice.label}</span>
                                {selectedVoice === voice.id && <span className="text-emerald-400">✓</span>}
                            </button>
                        ))}
                    </div>
                </div>
                <div className="bg-slate-900/40 p-4 rounded-xl border border-white/5">
                    <h3 className="text-amber-400 font-bold mb-3 font-sans">الأصوات الأنثوية</h3>
                    <div className="space-y-2">
                        {VOICES.female.map(voice => (
                            <button
                                key={voice.id}
                                onClick={() => setSelectedVoice(voice.id)}
                                className={`w-full flex items-center justify-between p-3 rounded-lg border transition-all font-sans ${selectedVoice === voice.id ? 'bg-amber-500/20 border-amber-500 text-amber-100' : 'border-slate-700 text-slate-400 hover:bg-white/5'}`}
                            >
                                <span>{voice.label}</span>
                                {selectedVoice === voice.id && <span className="text-amber-400">✓</span>}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            <div className="bg-slate-900/50 p-6 rounded-2xl border border-white/5 flex flex-col md:flex-row items-center justify-between gap-4 mt-auto">
                <div className="flex items-center gap-4 w-full md:w-auto">
                    <div className={`w-12 h-12 rounded-full flex items-center justify-center transition-colors ${isPlaying ? 'bg-amber-500 text-slate-900 animate-pulse' : 'bg-slate-700 text-slate-400'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
                        </svg>
                    </div>
                    <div>
                        <h3 className="text-white font-bold text-lg font-sans">
                             {VOICES.male.find(v => v.id === selectedVoice)?.label || VOICES.female.find(v => v.id === selectedVoice)?.label}
                        </h3>
                        <p className="text-sm text-slate-400 font-sans">صيغة MP3 عالية الجودة</p>
                    </div>
                </div>

                {audioUrl && (
                    <audio 
                        ref={audioRef} 
                        src={audioUrl} 
                        onEnded={() => setIsPlaying(false)}
                        onPlay={() => setIsPlaying(true)}
                        onPause={() => setIsPlaying(false)}
                        controls 
                        className="hidden" 
                    />
                )}

                <div className="flex gap-3 w-full md:w-auto justify-end">
                    {audioUrl ? (
                      <div className="flex gap-2">
                         <button 
                            onClick={() => { if (audioRef.current) { if (isPlaying) audioRef.current.pause(); else audioRef.current.play(); }}}
                            className="bg-slate-700 hover:bg-slate-600 text-white px-6 py-3 rounded-full font-bold transition-all border border-slate-500 font-sans"
                         >
                            {isPlaying ? 'إيقاف مؤقت' : '▶ معاينة'}
                         </button>
                         <a 
                            href={audioUrl} 
                            download={`lisan-voice-${Date.now()}.mp3`}
                            className="flex items-center gap-2 bg-amber-600 hover:bg-amber-500 text-white px-6 py-3 rounded-full font-bold transition-all shadow-lg font-sans"
                         >
                            <span>⬇ تحميل</span>
                         </a>
                      </div>
                    ) : (
                        <button 
                            onClick={handleSpeak} 
                            disabled={loading || !text}
                            className="bg-emerald-600 hover:bg-emerald-500 text-white px-8 py-3 rounded-full font-bold shadow-lg disabled:opacity-50 transition-all flex items-center justify-center gap-2 flex-1 md:flex-none font-sans"
                        >
                             {loading ? 'جاري التوليد...' : 'إنشاء الصوت'}
                        </button>
                    )}
                </div>
            </div>
          </div>
      ) : (
          // --- Voice Lab View ---
          <div className="flex-1 flex flex-col gap-6 animate-fadeIn">
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Visualizer & Recorder */}
                <div className="md:col-span-2 bg-slate-900/50 rounded-2xl border border-white/5 p-4 relative overflow-hidden min-h-[300px] flex flex-col items-center justify-center">
                    <canvas ref={canvasRef} width={600} height={300} className="absolute inset-0 w-full h-full opacity-50" />

                    {!labAudioUrl && !isRecording && (
                        <div className="z-10 text-center space-y-4">
                            <div className="w-20 h-20 rounded-full bg-slate-800 border border-slate-600 flex items-center justify-center mx-auto mb-4">
                                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-10 h-10 text-slate-400">
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 006-6v-1.5m-6 7.5a6 6 0 01-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 01-3-3V4.5a3 3 0 116 0v8.25a3 3 0 01-3 3z" />
                                </svg>
                            </div>
                            <button 
                                onClick={startRecording}
                                className="bg-red-600 hover:bg-red-500 text-white px-8 py-3 rounded-full font-bold shadow-[0_0_20px_rgba(220,38,38,0.4)] transition-all font-sans text-lg"
                            >
                                تسجيل صوتي (استنساخ)
                            </button>
                            <p className="text-slate-500 text-sm font-sans mt-2">سجل مقطعاً بصوتك لتنقيحه وتحسين جودته</p>
                        </div>
                    )}

                    {isRecording && (
                        <div className="z-10 text-center">
                            <div className="text-red-500 animate-pulse font-bold text-xl mb-4 font-sans">● جاري التسجيل...</div>
                            <button 
                                onClick={stopRecording}
                                className="bg-slate-700 hover:bg-slate-600 text-white px-8 py-2 rounded-full font-bold border border-slate-500 font-sans"
                            >
                                إيقاف
                            </button>
                        </div>
                    )}

                    {labAudioUrl && !isRecording && (
                         <div className="z-10 w-full px-8 flex flex-col items-center gap-4">
                            <audio src={labAudioUrl} controls className="w-full max-w-md" />
                            <button 
                                onClick={() => { setLabAudioUrl(null); setLabAudioBlob(null); setProcessedBlob(null); }}
                                className="text-slate-400 hover:text-white text-sm underline font-sans"
                            >
                                حذف وتسجيل جديد
                            </button>
                         </div>
                    )}
                </div>

                {/* Settings Panel */}
                <div className="bg-slate-800/40 rounded-2xl border border-white/5 p-6 flex flex-col gap-6">
                    <h3 className="text-xl font-bold text-white font-calligraphy border-b border-white/10 pb-2">أدوات المعالجة</h3>

                    <div className="space-y-4">
                        <label className="flex items-center justify-between cursor-pointer group">
                            <span className="text-slate-300 font-sans group-hover:text-white transition-colors">عزل الضجيج (Denoise)</span>
                            <div 
                                onClick={() => setEnableDenoise(!enableDenoise)}
                                className={`w-12 h-6 rounded-full relative transition-colors ${enableDenoise ? 'bg-emerald-500' : 'bg-slate-600'}`}
                            >
                                <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${enableDenoise ? 'left-1' : 'left-7'}`} />
                            </div>
                        </label>
                        <p className="text-xs text-slate-500">إزالة الوشوشة وترددات الخلفية المنخفضة.</p>

                        <div className="h-px bg-white/5 my-2" />

                        <label className="flex items-center justify-between cursor-pointer group">
                            <span className="text-slate-300 font-sans group-hover:text-white transition-colors">تحسين الصوت (Enhance)</span>
                            <div 
                                onClick={() => setEnableEnhance(!enableEnhance)}
                                className={`w-12 h-6 rounded-full relative transition-colors ${enableEnhance ? 'bg-amber-500' : 'bg-slate-600'}`}
                            >
                                <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${enableEnhance ? 'left-1' : 'left-7'}`} />
                            </div>
                        </label>
                        <p className="text-xs text-slate-500">ضغط الصوت وموازنة الترددات (EQ) لوضوح إذاعي.</p>
                    </div>

                    <div className="mt-auto">
                        <button 
                            onClick={processAudio}
                            disabled={!labAudioBlob || isProcessing || (!enableDenoise && !enableEnhance)}
                            className="w-full bg-gradient-to-r from-emerald-600 to-emerald-500 hover:from-emerald-500 hover:to-emerald-400 text-white font-bold py-3 rounded-xl shadow-lg disabled:opacity-50 disabled:cursor-not-allowed transition-all font-sans"
                        >
                            {isProcessing ? 'جاري المعالجة...' : 'تنفيذ التحسينات ✨'}
                        </button>
                    </div>
                </div>
             </div>

             {/* Results Section */}
             {processedBlob && (
                <div className="bg-emerald-900/20 border border-emerald-500/30 rounded-2xl p-6 flex flex-col md:flex-row items-center justify-between gap-4 animate-slideUp">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-emerald-500/20 rounded-full flex items-center justify-center text-emerald-400">
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                        </div>
                        <div>
                            <h4 className="text-white font-bold text-lg font-sans">تم تحسين النسخة المستنسخة</h4>
                            <p className="text-emerald-200/60 text-sm">تم تطبيق الفلاتر بنجاح.</p>
                        </div>
                    </div>
                    <div className="flex gap-3">
                         <a 
                            href={labAudioUrl!} 
                            download="lisan-cloned-enhanced.wav"
                            className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2 rounded-lg font-bold font-sans flex items-center gap-2"
                         >
                            <span>تحميل النسخة (WAV)</span>
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M12 12.75l-3.32-3.32m0 0l3.32-3.32m-3.32 3.32h7.905" />
                            </svg>
                         </a>
                    </div>
                </div>
             )}
          </div>
      )}
    </div>
  );
};

export default VoiceStudio;

