// Helper to convert AudioBuffer to WAV Blob
const bufferToWave = (abuffer: AudioBuffer, len: number) => {
  const numOfChan = abuffer.numberOfChannels;
  const length = len * numOfChan * 2 + 44;
  const buffer = new ArrayBuffer(length);
  const view = new DataView(buffer);
  const channels = [];
  let i;
  let sample;
  let offset = 0;
  let pos = 0;

  // write WAVE header
  setUint32(0x46464952); // "RIFF"
  setUint32(length - 8); // file length - 8
  setUint32(0x45564157); // "WAVE"

  setUint32(0x20746d66); // "fmt " chunk
  setUint32(16); // length = 16
  setUint16(1); // PCM (uncompressed)
  setUint16(numOfChan);
  setUint32(abuffer.sampleRate);
  setUint32(abuffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
  setUint16(numOfChan * 2); // block-align
  setUint16(16); // 16-bit (hardcoded in this example)

  setUint32(0x61746164); // "data" - chunk
  setUint32(length - pos - 4); // chunk length

  // write interleaved data
  for(i = 0; i < abuffer.numberOfChannels; i++)
    channels.push(abuffer.getChannelData(i));

  while(pos < len) {
    for(i = 0; i < numOfChan; i++) {
      sample = Math.max(-1, Math.min(1, channels[i][pos])); // clamp
      sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; // scale to 16-bit signed int
      view.setInt16(44 + offset, sample, true); 
      offset += 2;
    }
    pos++;
  }

  return new Blob([buffer], {type: "audio/wav"});

  function setUint16(data: number) {
    view.setUint16(pos, data, true);
    pos += 2;
  }
  function setUint32(data: number) {
    view.setUint32(pos, data, true);
    pos += 4;
  }
};

const VoiceStudio: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'tts' | 'lab'>('tts');

  // --- TTS State ---
  const [voices, setVoices] = useState<VoiceLibrary>(INITIAL_VOICES);
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [selectedVoice, setSelectedVoice] = useState('Zephyr');
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // --- Voice Lab State ---
  const [isRecording, setIsRecording] = useState(false);
  const [labAudioBlob, setLabAudioBlob] = useState<Blob | null>(null);
  const [processedBlob, setProcessedBlob] = useState<Blob | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [labAudioUrl, setLabAudioUrl] = useState<string | null>(null);
  const [voiceName, setVoiceName] = useState(''); // State for naming the voice

  // Lab Settings
  const [enableDenoise, setEnableDenoise] = useState(true);
  const [enableEnhance, setEnableEnhance] = useState(true);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animationFrameRef = useRef<number>(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- TTS Functions ---
  const createMp3Blob = (samples: Int16Array, sampleRate: number = 24000) => {
    const lame = window.lamejs;
    if (!lame) return null;
    const mp3encoder = new lame.Mp3Encoder(1, sampleRate, 128);
    const mp3Data = [];
    const sampleBlockSize = 1152;
    for (let i = 0; i < samples.length; i += sampleBlockSize) {
      const sampleChunk = samples.subarray(i, i + sampleBlockSize);
      const mp3buf = mp3encoder.encodeBuffer(sampleChunk);
      if (mp3buf.length > 0) mp3Data.push(mp3buf);
    }
    const mp3buf = mp3encoder.flush();
    if (mp3buf.length > 0) mp3Data.push(mp3buf);
    return new Blob(mp3Data, { type: 'audio/mp3' });
  };

  const handleSpeak = async () => {
    if (!text) return;
    if (audioUrl) { URL.revokeObjectURL(audioUrl); setAudioUrl(null); }
    setIsPlaying(false);
    setLoading(true);
    try {
        const rawBuffer = await GeminiService.generateSpeech(text, selectedVoice);
        const int16Data = new Int16Array(rawBuffer);
        const mp3Blob = createMp3Blob(int16Data, 24000);
        if (mp3Blob) {
            const url = URL.createObjectURL(mp3Blob);
            setAudioUrl(url);
            setTimeout(() => { if (audioRef.current) { audioRef.current.play(); setIsPlaying(true); } }, 100);
        }
    } catch (error) {
        console.error(error);
        alert("حدث خطأ أثناء توليد الصوت.");
    } finally {
        setLoading(false);
    }
  };

  // --- Voice Lab Functions ---

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('audio/')) {
        alert("يرجى اختيار ملف صوتي صحيح.");
        return;
    }

    setLabAudioBlob(file);
    setLabAudioUrl(URL.createObjectURL(file));
    setProcessedBlob(null);
    e.target.value = ''; // Reset input
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/wav' });
        setLabAudioBlob(audioBlob);
        setLabAudioUrl(URL.createObjectURL(audioBlob));
        setProcessedBlob(null); // Reset processed if new recording
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
      visualize(stream);
    } catch (err) {
      console.error(err);
      alert("يرجى السماح بصلاحية الميكروفون للتسجيل.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
      setIsRecording(false);
      cancelAnimationFrame(animationFrameRef.current);
    }
  };

  const visualize = (stream: MediaStream) => {
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const source = audioCtx.createMediaStreamSource(stream);
    const analyzer = audioCtx.createAnalyser();
    analyzer.fftSize = 256;
    source.connect(analyzer);

    const bufferLength = analyzer.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);
    const canvas = canvasRef.current;
    if(!canvas) return;
    const ctx = canvas.getContext('2d');
    if(!ctx) return;

    const draw = () => {
        animationFrameRef.current = requestAnimationFrame(draw);
        analyzer.getByteFrequencyData(dataArray);
        ctx.fillStyle = 'rgb(15, 23, 42)'; // Background
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        const barWidth = (canvas.width / bufferLength) * 2.5;
        let barHeight;
        let x = 0;

        for(let i = 0; i < bufferLength; i++) {
            barHeight = dataArray[i] / 2;
            const r = barHeight + 25 * (i/bufferLength);
            const g = 250 * (i/bufferLength);
            const b = 50;

            ctx.fillStyle = `rgb(${r},${g},${b})`;
            ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
            x += barWidth + 1;
        }
    };
    draw();
  };

  const processAudio = async () => {
    if (!labAudioBlob) return;
    setIsProcessing(true);

    try {
        const arrayBuffer = await labAudioBlob.arrayBuffer();
        const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const decodedBuffer = await audioCtx.decodeAudioData(arrayBuffer);

        // Offline Context for rendering
        const offlineCtx = new OfflineAudioContext(decodedBuffer.numberOfChannels, decodedBuffer.length, decodedBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = decodedBuffer;

        let lastNode: AudioNode = source;

        // 1. Denoise (Highpass to remove rumble + Lowpass for hiss)
        if (enableDenoise) {
            const highpass = offlineCtx.createBiquadFilter();
            highpass.type = 'highpass';
            highpass.frequency.value = 100; // Remove sub-bass rumble
            lastNode.connect(highpass);
            lastNode = highpass;

            const lowpass = offlineCtx.createBiquadFilter();
            lowpass.type = 'lowpass';
            lowpass.frequency.value = 12000; // Soften extreme highs
            lastNode.connect(lowpass);
            lastNode = lowpass;
        }

        // 2. Enhance (Compressor + EQ)
        if (enableEnhance) {
            // Dynamics Compressor for "Radio Voice" consistency
            const compressor = offlineCtx.createDynamicsCompressor();
            compressor.threshold.value = -24;
            compressor.knee.value = 30;
            compressor.ratio.value = 4; // Moderate compression
            compressor.attack.value = 0.003;
            compressor.release.value = 0.25;
            lastNode.connect(compressor);
            lastNode = compressor;

            // Presence EQ boost
            const eq = offlineCtx.createBiquadFilter();
            eq.type = 'peaking';
            eq.frequency.value = 2500; // Vocal clarity range
            eq.Q.value = 1;
            eq.gain.value = 3; // +3dB
            lastNode.connect(eq);
            lastNode = eq;
        }

        lastNode.connect(offlineCtx.destination);
        source.start();

        const renderedBuffer = await offlineCtx.startRendering();
        const waveBlob = bufferToWave(renderedBuffer, renderedBuffer.length);

        const blobUrl = URL.createObjectURL(waveBlob);
        setProcessedBlob(waveBlob);
        setLabAudioUrl(blobUrl);

    } catch (e) {
        console.error("Audio Processing Error", e);
        alert("حدث خطأ أثناء معالجة الصوت.");
    } finally {
        setIsProcessing(false);
    }
  };

  const addVoiceToLibrary = () => {
    if (!voiceName.trim()) {
        alert("يرجى إدخال اسم للصوت");
        return;
    }

    const newVoiceId = `cloned-${Date.now()}`;
    const newVoice: VoiceOption = {
        id: newVoiceId,
        label: `${voiceName} (مستنسخ)`,
        isCustom: true
    };

    setVoices(prev => ({
        ...prev,
        cloned: [...prev.cloned, newVoice]
    }));

    // Reset Lab State
    setLabAudioBlob(null);
    setLabAudioUrl(null);
    setProcessedBlob(null);
    setVoiceName('');

    // Switch to TTS and select the new voice
    setActiveTab('tts');
    setSelectedVoice(newVoiceId);
  };

  return (
    <div className="flex flex-col h-full p-4 md:p-8 max-w-5xl mx-auto">
       <div className="mb-6 border-b border-white/10 pb-4 flex justify-between items-end">
        <div>
            <h2 className="text-3xl font-calligraphy text-amber-400 mb-2">استوديو الصوتيات</h2>
            <p className="text-slate-400 font-light font-sans">توليد الكلام، استنساخ الصوت، وتنقيح التسجيلات.</p>
        </div>

        {/* Tab Switcher */}
        <div className="flex bg-slate-900/60 rounded-lg p-1 border border-white/10">
            <button 
                onClick={() => setActiveTab('tts')}
                className={`px-4 py-2 rounded-md font-sans text-sm transition-all ${activeTab === 'tts' ? 'bg-amber-500 text-slate-900 font-bold' : 'text-slate-400 hover:text-white'}`}
            >
                الناطق الآلي
            </button>
            <button 
                onClick={() => setActiveTab('lab')}
                className={`px-4 py-2 rounded-md font-sans text-sm transition-all ${activeTab === 'lab' ? 'bg-emerald-500 text-slate-900 font-bold' : 'text-slate-400 hover:text-white'}`}
            >
                مختبر الصوت (استنساخ)
            </button>
        </div>
      </div>

      {activeTab === 'tts' ? (
          // --- TTS View ---
          <div className="flex-1 flex flex-col gap-6 animate-fadeIn">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="md:col-span-2">
                     <textarea
                        value={text}
                        onChange={(e) => setText(e.target.value)}
                        placeholder="أدخل النص هنا للاستماع إليه..."
                        className="w-full bg-slate-800/40 border border-slate-600 rounded-2xl p-6 text-xl font-sans text-white focus:ring-2 focus:ring-amber-500 outline-none resize-none leading-loose min-h-[150px]"
                    />
                </div>

                {/* Cloned Voices Category */}
                {voices.cloned.length > 0 && (
                    <div className="md:col-span-2 bg-indigo-900/20 p-4 rounded-xl border border-indigo-500/30">
                        <h3 className="text-indigo-400 font-bold mb-3 font-sans flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse"/>
                            أصواتي المستنسخة
                        </h3>
                        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                            {voices.cloned.map(voice => (
                                <button
                                    key={voice.id}
                                    onClick={() => setSelectedVoice(voice.id)}
                                    className={`flex items-center justify-between p-3 rounded-lg border transition-all font-sans ${selectedVoice === voice.id ? 'bg-indigo-500/20 border-indigo-500 text-indigo-100' : 'border-slate-700 text-slate-400 hover:bg-white/5'}`}
                                >
                                    <span>{voice.label}</span>
                                    {selectedVoice === voice.id && <span className="text-indigo-400">✓</span>}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                <div className="bg-slate-900/40 p-4 rounded-xl border border-white/5">
                    <h3 className="text-emerald-400 font-bold mb-3 font-sans">الأصوات الذكورية</h3>
