                        <div className="h-px bg-white/5 my-2" />

                        <label className="flex items-center justify-between cursor-pointer group">
                            <span className="text-slate-300 font-sans group-hover:text-white transition-colors">تحسين الصوت (Enhance)</span>
                            <div 
