                    </div>

                    <div className="flex gap-3 items-center border-r border-white/10 pr-4 mr-2">
                         <a 
                            href={labAudioUrl!} 
                            download="lisan-cloned-enhanced.wav"
                            className="bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg font-bold font-sans text-sm flex items-center gap-2"
                         >
                            <span>تحميل WAV</span>
                            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4">
                                <path strokeLinecap="round" strokeLinejoin="round" d="M3 16.5v2.25A2.25 2.25 0 005.25 21h13.5A2.25 2.25 0 0021 18.75V16.5M12 12.75l-3.32-3.32m0 0l3.32-3.32m-3.32 3.32h7.905" />
                            </svg>
                         </a>
                    </div>
                </div>
             )}
          </div>
      )}
    </div>
  );
};

export default VoiceStudio;

import { GoogleGenAI, Modality } from "@google/genai";

// Helper to get a fresh instance with the latest API key
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const GeminiService = {
  /**
   * General Deep Search & Linguistics Analysis
   * Uses gemini-3-pro-preview for complex reasoning (Nahw, Bayan, Logic)
   * Supports multimodal input (Text + PDF/Images)
   */
  async deepSearch(query: string, context: string = '', fileData?: { mimeType: string; data: string }): Promise<string> {
    try {
      const ai = getAI();
      const modelId = 'gemini-3-pro-preview';
      const systemInstruction = `
        أنت "لسان"، خبير لغوي عالمي متخصص في اللغة العربية الفصحى وعلومها (نحو، صرف، بيان، بديع، عروض، منطق).
        دورك هو تقديم إجابات دقيقة جداً، علمية، وموثقة.
        - إذا سُئلت عن الإعراب، فصل القول.
        - إذا سُئلت عن الشعر، حلل الوزن والبحر.
        - إذا أرفق ملف، قم بتحليل محتواه لغوياً وأدبياً بدقة.
        - إذا لم تكن المعلومة مؤكدة، قل "لا أملك معلومة دقيقة".
        - أسلوبك رصين، عربي فصيح، وجذاب.
      `;

      const parts: any[] = [{ text: `سياق سابق: ${context}\n\nسؤالي هو: ${query}` }];

      if (fileData) {
        // Prepend file data to the parts
        parts.unshift({
          inlineData: {
            mimeType: fileData.mimeType,
            data: fileData.data
          }
        });
      }

      const response = await ai.models.generateContent({
        model: modelId,
        contents: [
          { role: 'user', parts: parts }
        ],
        config: {
          systemInstruction,
          temperature: 0.3, // Low temperature for factual accuracy
        }
      });

      return response.text || "عذراً، لم أتمكن من استخراج إجابة.";
    } catch (error) {
      console.error("Deep search error", error);
      throw error;
    }
  },

  /**
   * Precise Tashkeel (Diacritics)
   * Uses gemini-2.5-flash for speed and accuracy in pattern matching
   */
  async addDiacritics(text: string): Promise<string> {
    try {
      const ai = getAI();
      const modelId = 'gemini-2.5-flash';
      const prompt = `
        مهمتك هي تشكيل النص التالي تشكيلاً كاملاً دقيقاً (نحوياً وصرفياً) حسب قواعد اللغة العربية الفصحى.
        لا تضف أي شرح، فقط أعد كتابة النص مشكولاً.

        النص:
        ${text}
      `;

      const response = await ai.models.generateContent({
        model: modelId,
        contents: prompt,
        config: {
          temperature: 0.1
        }
      });

      return response.text || text;
    } catch (error) {
      console.error("Tashkeel error", error);
      throw error;
    }
  },

  /**
   * Standard Art Generation (Flash)
   */
  async generateArt(prompt: string, style: 'calligraphy' | 'manuscript' | 'modern'): Promise<string> {
    try {
      const ai = getAI();
      // Logic to enhance prompt based on style
      let enhancedPrompt = prompt;
      if (style === 'calligraphy') {
        enhancedPrompt = `Arabic calligraphy art, masterpiece, high quality, text: "${prompt}", intricate details, islamic patterns.`;
      } else if (style === 'manuscript') {
        enhancedPrompt = `Ancient Arabic manuscript page, aged paper, gold leaf illumination, thuluth script, historical artifact, ${prompt}`;
      } else {
        enhancedPrompt = `Modern Islamic art, abstract geometric patterns, 3d render, high contrast, ${prompt}`;
      }

      // Use gemini-2.5-flash-image for speed/standard generation
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: enhancedPrompt }] },
      });

      // Iterate to find image part
      for (const candidate of response.candidates || []) {
        for (const part of candidate.content.parts) {
          if (part.inlineData && part.inlineData.mimeType.startsWith('image')) {
             return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          }
        }
      }

      throw new Error("No image generated");
    } catch (error) {
      console.error("Art gen error", error);
      throw error;
    }
  },

  /**
   * Text to Speech (Correct Arabic Pronunciation)
   * Supports specific voice selection.
   * Handles custom/cloned voice IDs gracefully by fallback (as API strictness requires valid enum/strings).
   */
  async generateSpeech(text: string, voiceName: string = 'Zephyr'): Promise<ArrayBuffer> {
    try {
      const ai = getAI();

      // Determine effective voice name for API call
      // If voiceName is a custom ID (starts with cloned-), use a high quality fallback.
      // We cannot force an invalid voice name string to the API.
      const isCustom = voiceName.startsWith('cloned-');
      const effectiveVoice = isCustom ? 'Zephyr' : voiceName;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: effectiveVoice }, 
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data returned");

      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;

    } catch (error) {
      console.error("TTS error", error);
      throw error;
    }
  }
};
